import{_ as n,a0 as s,w as d,s as p,ao as r,I as e,a1 as o,A as i,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"如果托瓦兹接受了乔布斯的职业建议会怎样？ | LCTT x X-CMD","titleTemplate":false,"description":"如果托瓦兹接受了乔布斯的职业建议会怎样？ | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如果托瓦兹接受了乔布斯的职业建议会怎样？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如果托瓦兹接受了乔布斯的职业建议会怎样？ | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/What if Linus Torvalds Would Have Accepted Job Proposal of Steve Jobs","title":"如果托瓦兹接受了乔布斯的职业建议会怎样？","tag":"201404","desc":""},"relativePath":"201404/What if Linus Torvalds Would Have Accepted Job Proposal of Steve Jobs.md","filePath":"[post].md"}'),u={name:"201404/What if Linus Torvalds Would Have Accepted Job Proposal of Steve Jobs.md"};function h(f,a,b,m,x,T){const l=s("Link");return d(),p("div",null,[a[14]||(a[14]=r('<h1 id="如果托瓦兹接受了乔布斯的职业建议会怎样" tabindex="-1">如果托瓦兹接受了乔布斯的职业建议会怎样？ <a class="header-anchor" href="#如果托瓦兹接受了乔布斯的职业建议会怎样" aria-label="Permalink to “如果托瓦兹接受了乔布斯的职业建议会怎样？”">​</a></h1><p>苹果公司创始人史蒂芬乔布斯曾为 Linux 和 Git 这两个伟大的开源项目创始人托瓦兹提供工作。托瓦兹从未见过微软公司的比尔盖茨，但却在2000年的时候遇上了乔布斯。那时候的他任职于美国半导体设计公司全美达（Transmeta）。乔布斯邀请托瓦兹去位于库比蒂诺的苹果总部工作，为他提供丰厚的薪水和优越的职位，但是他在苹果的工作却是与Linux无关的。正是由于这个原因托瓦兹拒绝了乔布斯的邀请。况且，托瓦兹根本就不喜欢苹果操作系统的内核Mach。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Linux-Torvalds.jpg" alt="Linus Torvalds"></p><h3 id="如果托瓦兹接受了邀请会怎么样" tabindex="-1">如果托瓦兹接受了邀请会怎么样？### <a class="header-anchor" href="#如果托瓦兹接受了邀请会怎么样" aria-label="Permalink to “如果托瓦兹接受了邀请会怎么样？###”">​</a></h3><p>在那个时候如果托瓦兹答应乔布斯去苹果工作，那现在的世界将会不一样。我们不会有 Linux，Kindle 和 Android。互联网上一半以上的内容和超过九成的服务器都将不复存在。毫不夸张的说，世界绝不可能是现在这个样子。</p><h3 id="托瓦兹拒绝乔布斯的负面影响有哪些" tabindex="-1">托瓦兹拒绝乔布斯的负面影响有哪些？ <a class="header-anchor" href="#托瓦兹拒绝乔布斯的负面影响有哪些" aria-label="Permalink to “托瓦兹拒绝乔布斯的负面影响有哪些？”">​</a></h3><p>原本我们可以看到托瓦兹和乔布斯两个天才在一起工作。或许世界也将从他们俩的合作中获益。但可以肯定的是，我们将冒着失去 Linux 的风险。</p><h3 id="托瓦兹为自己代言" tabindex="-1">托瓦兹为自己代言 <a class="header-anchor" href="#托瓦兹为自己代言" aria-label="Permalink to “托瓦兹为自己代言”">​</a></h3><p>有时候，托瓦兹由于他那些极具争议的言论而显得傲慢。但这与他对世界的贡献是不相符的。他创造了 Linux 和 Git 两个极好的开源项目，并使他们自由免费。有许多攻讦托瓦兹的言论说他从没有拿出他的部分收入来改善这个世界。但事实上，托瓦兹对于他人贡献是难以想象的。托瓦兹将他最完美的作品变成免费。而他本可以从中获得数以亿计的收入。他将他所拥有的一切无私平等地奉献给了整个世界。</p><h3 id="托瓦兹作为一个普通人" tabindex="-1">托瓦兹作为一个普通人 <a class="header-anchor" href="#托瓦兹作为一个普通人" aria-label="Permalink to “托瓦兹作为一个普通人”">​</a></h3><p>Linux 内核的总设计师是一个很好又有趣的人。他谈论着世界的各个方面。他的博客涉及孩子、万圣节和祖国等方方面面。你可以通过博客和 G+ 来关注他。</p><h4 id="关注托瓦兹的博客" tabindex="-1">关注托瓦兹的博客 <a class="header-anchor" href="#关注托瓦兹的博客" aria-label="Permalink to “关注托瓦兹的博客”">​</a></h4>',12)),e("ul",null,[e("li",null,[o(l,{href:"http://torvalds-family.blogspot.in/"},{default:i(()=>[...a[0]||(a[0]=[t("http://torvalds-family.blogspot.in/",-1)])]),_:1})]),e("li",null,[o(l,{href:"http://www.linuxfoundation.org/blogs/linus-torvalds"},{default:i(()=>[...a[1]||(a[1]=[t("http://www.linuxfoundation.org/blogs/linus-torvalds",-1)])]),_:1})])]),a[15]||(a[15]=e("h4",{id:"关注托瓦兹的g",tabindex:"-1"},[t("关注托瓦兹的G+ "),e("a",{class:"header-anchor",href:"#关注托瓦兹的g","aria-label":"Permalink to “关注托瓦兹的G+”"},"​")],-1)),e("ul",null,[e("li",null,[o(l,{href:"https://plus.google.com/+LinusTorvalds/posts"},{default:i(()=>[...a[2]||(a[2]=[t("https://plus.google.com/+LinusTorvalds/posts",-1)])]),_:1})])]),a[16]||(a[16]=r('<h3 id="托瓦兹鲜为人知之事" tabindex="-1">托瓦兹鲜为人知之事 <a class="header-anchor" href="#托瓦兹鲜为人知之事" aria-label="Permalink to “托瓦兹鲜为人知之事”">​</a></h3><ul><li>年薪：1000万美元</li><li>身价：15亿美元</li><li>版本控制系统RCS，Git和Linux内核的创始人。</li><li>托瓦兹更乐于使用开源软件，但他从不介意通过商业软件来获得最佳的效果。</li><li>在2008年和2012年的采访中，托瓦兹表示自己喜欢使用 Fedora 系统是由于 Fedora 对于 PowerPC 系列处理器的良好支持。</li><li>由于 Linux 基金会的赞助，托瓦兹可以全身心地投入到Linux的开发中去。</li></ul><h3 id="托瓦兹的至理名言" tabindex="-1">托瓦兹的至理名言 <a class="header-anchor" href="#托瓦兹的至理名言" aria-label="Permalink to “托瓦兹的至理名言”">​</a></h3><p>托瓦兹说过的一些话.</p><h4 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to “引用”">​</a></h4><blockquote><p>“托瓦兹不戴眼镜，他已经把 X11 系统当作了他的眼镜，所以他不再需要眼镜。”</p><p>“当你说，我写了一款摧毁 Windows 的软件，人们只会一脸茫然地对你说，我已经在使用这款免费的软件。”</p><p>“只有懦夫才使用磁盘来维护备份的文件，强者将文件上传至公共的 FTP 服务器让所有人来下载。”</p><p>“你看，为了写出 Linux 这样的系统，你不仅需要是一位好的程序员，还要是一个狡猾的坏蛋。”</p></blockquote><h4 id="名言" tabindex="-1">名言 <a class="header-anchor" href="#名言" aria-label="Permalink to “名言”">​</a></h4><blockquote><p>“让 Linux 在 GPL 协议下自由发展是我做的过最精彩的事。”</p></blockquote><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>有些人认为，如果托瓦兹没有创造出 Linux，其他人也可能创造出类似的系统。例如“米歇尔”也许会写出一款叫做“Michel”的操作系统。说这些并不是让我们低估托瓦兹的能力，牺牲以及他所作的贡献。</p><p>托瓦兹是一个救世主、极客、开发者、美国宇航局研究实验室的管理、白帽子黑客等其他托瓦兹所做过的职业。托瓦兹的优越感对于他自己而言没有任何问题。世界也会感谢他的。</p><p>这是全部了，我会再次和大家见面并带来你们喜欢的文章。请在下面的评论区分享你们宝贵的意见。</p><hr>',13)),e("p",null,[a[4]||(a[4]=t("via: ",-1)),o(l,{href:"http://www.tecmint.com/what-if-linus-torvalds-would-have-accepted-job-proposal-of-steve-jobs/"},{default:i(()=>[...a[3]||(a[3]=[t("http://www.tecmint.com/what-if-linus-torvalds-would-have-accepted-job-proposal-of-steve-jobs/",-1)])]),_:1})]),e("p",null,[a[7]||(a[7]=t("译者：",-1)),o(l,{href:"https://github.com/YangYuxiang"},{default:i(()=>[...a[5]||(a[5]=[t("YangYuxiang",-1)])]),_:1}),a[8]||(a[8]=t(" 校对：",-1)),o(l,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...a[6]||(a[6]=[t("Caroline",-1)])]),_:1})]),e("p",null,[a[11]||(a[11]=t("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[9]||(a[9]=[t("LCTT",-1)])]),_:1}),a[12]||(a[12]=t(" 原创翻译，",-1)),o(l,{href:"http://linux.cn/"},{default:i(()=>[...a[10]||(a[10]=[t("Linux中国",-1)])]),_:1}),a[13]||(a[13]=t(" 荣誉推出",-1))])])}const g=n(u,[["render",h]]);export{P as __pageData,g as default};
